and a.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and a.FINPROD_MARKET_ID LIKE CONCAT('%',CONCAT(#{finprodMarketId,jdbcType=VARCHAR},'%'))
and c.FUTURES_CONTRACT_ID in
#{item}
and a.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}
and b.TYPE_6 in
#{item}
and c.LAST_TRADE_DATE >= to_date(#{lastTradeDateStart},'yyyy-MM-dd')
and c.LAST_TRADE_DATE <= to_date(#{lastTradeDateEnd},'yyyy-MM-dd')
